document.addEventListener("DOMContentLoaded",(()=>{const t=document.getElementById("salesData");fetch("/api/sales").then((t=>t.json())).then((n=>{if(0===n.length)return void(t.innerHTML="<p>No sales data available.</p>");const e=document.createElement("table");e.innerHTML=`\n                <thead>\n                    <tr>\n                        <th>ID</th>\n                        <th>Account Reference</th>\n                        <th>Time of Sale</th>\n                        <th>Total Amount</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    ${n.map((t=>`\n                        <tr>\n                            <td>${t.id}</td>\n                            <td>${t.accountReference}</td>\n                            <td>${t.timeOfSale}</td>\n                            <td>${t.totalNetAmountWithTax}</td>\n                        </tr>\n                    `)).join("")}\n                </tbody>\n            `,t.appendChild(e)})).catch((n=>{console.error("Error fetching sales data:",n),t.innerHTML="<p>Error loading sales data. Please try again later.</p>"}))}));